export function shipInputKey(input: ShipInput): string {
  return `${input.thrust}|${input.yaw}|${input.pitch}|${input.roll}|${input.up}|${
    input.boost ?? 0
  }`;
}

/** True when the frame carries any real control demand (not the idle frame). */
export function anyFlightDemand(input: ShipInput): boolean {
  return (
    input.thrust !== 0 ||
    input.yaw !== 0 ||
    input.pitch !== 0 ||
    input.roll !== 0 ||
    input.up !== 0 ||
    (input.boost ?? 0) !== 0
  );
}

/**
 * TASK-86: the FLIGHT scheme a wire-docked ship's demand must be read
 * through. A pad-docked ship carries the server flightRegime 'surface',
 * which remaps the keys to the CHARACTER scheme (W = walk) — zero flight
 * demand — so the dock gate (TASK-78) suppressed the very frame the
 * server's "first input = take-off" contract needs. 'surface' maps to the
 * atmosphere scheme (full flight + VTOL lift off the pad); space/atmosphere
 * map to themselves.
 */
export function dockedFlightScheme(regime: Regime): ControlScheme {
  return CONTROL_SCHEMES[regime === 'surface' ? 'atmosphere' : regime];
}

const EMPTY_PRESSED: ReadonlySet<string> = new Set();

/**
 * The pressed set the FLIGHT loop reads: the star chart open never flies
 * the ship — the effective set is empty (the loop then sends a coast
 * frame on the key change, stopping any held thrust). The captured set is
 * never mutated: the keys are still physically held and resume when the
 * chart closes. (Typing in chat is already excluded upstream by the key
 * capture — the same rules as the on-foot capture.)
 */
export function effectiveFlightPressed(
  pressed: ReadonlySet<string>,
  opts: { chartOpen: boolean },
): ReadonlySet<string> {
  return opts.chartOpen ? EMPTY_PRESSED : pressed;
}

text:
The client side is done, and the committed tests are green. Next up is the physics work.

**Change 1: `flight.ts` — VTOL_LIFT = 1.35 × GRAVITY**

Update the doc comment:
```ts
/**
 * VTOL lift at input.up = 1 (u/s²). 1.35× GRAVITY (TASK-86): full VTOL
 * demand gives a net 0.35·g climb, so a pad-docked ship can take off on
 * the VTOL key alone (the pre-TASK-86 value was exactly GRAVITY — neutral
 * buoyancy — which made a pad dock inescapable: lift cancelled gravity and
 * the pad machine re-docked any slow ship). Hover is no longer the rest
 * point: full VTOL climbs to the drag-limited terminal speed, and a light
 * touch (up < 0.74) still hovers.
 */
export const VTOL_LIFT = 1.35 * GRAVITY;
```

Wait — "light touch (up < 0.74) hovers": the hover demand is where up·VTOL_LIFT = g → up = 1/1.35 = 0.74. Since the key is binary (0/1), hover is unreachable with the key; partial demand isn't available from the keyboard. So "hover converges to vel.y = 0" was the old doc's story. The new behavior: full VTOL climbs. I'll phrase it that way.

Also, the file's header doc says (lines 25-28): "'surface': landed. Integrates with the same atmosphere physics (drag, gravity, VTOL, ground clamp), so a landed ship rests on the terrain and can VTOL-lift off" — this is now accurate.

**Change 2: hover test in `flight.test.ts`**

Old:
```ts
it('VTOL hover converges: lift cancels gravity, drag damps vel.y to 0', () => {
  const planet = atmo(1);
  const s = runSteps({...pos vec(0,200,0), vel vec(0,-8,0)...}, { ...NO_INPUT, up: 1 }, DT, 600, 'atmosphere', planet);
  expect(Math.abs(s.vel.y)).toBeLessThan(0.1);
  expect(200 - s.pos.y).toBeLessThan(12);
  const held = runSteps(s, { ...NO_INPUT, up: 1 }, DT, 600, 'atmosphere', planet);
  expect(Math.abs(held.vel.y)).toBeLessThan(0.1);
  expect(Math.abs(held.pos.y - s.pos.y)).toBeLessThan(3);
});
```

New (climb):
```ts
it('VTOL full lift climbs (TASK-86): net 0.35·g up, drag caps the climb speed', () => {
  const planet = atmo(1);
  // Falling at -8 u/s, full VTOL reverses the fall: net lift is now
  // 1.35·g − g = 0.35·g (TASK-86 climb margin) + drag opposing the fall.
  const s = runSteps({pos (0,200,0), vel (0,-8,0)}, { ...NO_INPUT, up: 1 }, DT, 600, 'atmosphere', planet);
  expect(s.vel.y, 'climbing').toBeGreaterThan(1);
  expect(s.pos.y, 'gained altitude').toBeGreaterThan(200);
  // The climb is drag-limited (terminal v = √(0.35·g / (k·f)) — with
  // density 1 at alt 200 that is ≈ 3.1 u/s), never unbounded.
  expect(s.vel.y).toBeLessThan(6);
